#!/bin/bash
set -euo pipefail
umask 077
[[ $EUID -eq 0 ]] || { echo '请用 sudo bash 执行'; exit 1; }
exec 9>/run/football-injury-view-update.lock
flock -n 9 || { echo '更新正在运行'; exit 1; }
test -s /opt/football-injuries/collector.py
test -s /opt/football-web/web.py
test -s /etc/football-injuries/key
backup=/var/backups/football-injury-view-$(date +%Y%m%d-%H%M%S)
mkdir -p "$backup"
cp -a /opt/football-web "$backup/web"
cp -a /opt/football-injuries/collector.py "$backup/collector.py"
rollback() {
 echo "更新失败，恢复原文件。备份：$backup"
 systemctl disable --now football-injury-view.timer 2>/dev/null || true
 systemctl stop football-injury-view.service football-injuries.service 2>/dev/null || true
 cp -a "$backup/web/." /opt/football-web/
 cp -a "$backup/collector.py" /opt/football-injuries/collector.py
 systemctl restart football-web.service || true
 systemctl start football-injuries.timer || true
}
trap rollback ERR
systemctl stop football-injuries.timer football-injuries.service
python3 - <<'INSTALL_PY'
import base64,grp,os,py_compile
from pathlib import Path
FILES={'collector.py': '', 'injury_view.py': '', 'publish_injuries.py': ''}
for name,data in FILES.items():
 p=Path('/opt/football-injuries/collector.py') if name=='collector.py' else Path('/opt/football-web')/name
 t=p.with_suffix('.new');t.write_bytes(base64.b64decode(data));py_compile.compile(str(t),doraise=True)
 t.chmod(0o600 if name=='collector.py' else 0o640);os.chown(t,0,0 if name=='collector.py' else grp.getgrnam('footballweb').gr_gid);os.replace(t,p)
p=Path('/opt/football-web/web.py');s=p.read_text()
if '# injury-view-v1' not in s:
 anchor='  return result\n'
 if s.count(anchor)!=1:raise RuntimeError('看板代码版本不兼容，已停止更新')
 s=s.replace(anchor,"  # injury-view-v1\n  from injury_view import attach as attach_injuries\n  result['injury_summary']=attach_injuries(rows)\n"+anchor)
 t=p.with_suffix('.new');t.write_text(s);py_compile.compile(str(t),doraise=True);t.chmod(0o640);os.chown(t,0,grp.getgrnam('footballweb').gr_gid);os.replace(t,p)
p=Path('/opt/football-web/app.js');s=p.read_text()
if '// injury-view-v1' not in s:
 anchor='for(const s of m.odds_sources)'
 if s.count(anchor)!=1:raise RuntimeError('看板前端版本不兼容，已停止更新')
 s=s.replace(anchor,base64.b64decode('').decode()+'\n'+anchor);p.write_text(s)

INSTALL_PY
cat > /etc/systemd/system/football-injury-view.service <<'UNIT'
[Unit]
Description=Publish private injury dashboard cache
After=football-injuries.service
[Service]
Type=oneshot
ExecStart=/usr/bin/python3 /opt/football-web/publish_injuries.py
UMask=0077
NoNewPrivileges=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=/opt/football-web
UNIT
cat > /etc/systemd/system/football-injury-view.timer <<'UNIT'
[Unit]
Description=Refresh injury dashboard cache every five minutes without API calls
[Timer]
OnBootSec=2min
OnUnitActiveSec=5min
[Install]
WantedBy=timers.target
UNIT
# Five bounded requests may take longer than the original three-request timeout.
mkdir -p /etc/systemd/system/football-injuries.service.d
cat > /etc/systemd/system/football-injuries.service.d/view.conf <<'UNIT'
[Service]
TimeoutStartSec=180
UNIT
systemctl daemon-reload
echo '正在查询赛程和伤停，通常数秒；网络慢时最多约三分钟。'
systemctl start football-injuries.service
systemctl start football-injury-view.service
systemctl enable --now football-injuries.timer football-injury-view.timer
systemctl restart football-web.service
python3 - <<'VERIFY_PY'
import json,time,urllib.request
c=json.load(open('/etc/football-web/access.json'))
op=urllib.request.build_opener(urllib.request.ProxyHandler({}))
for attempt in range(8):
 try:
  req=urllib.request.Request('http://127.0.0.1:8787/ui-api/data',headers={'Authorization':'Bearer '+c['api_key']})
  with op.open(req,timeout=20) as r:d=json.load(r)
  assert 'injury_summary' in d and all('injuries' in m for m in d['matches'])
  print('INJURY_VIEW_API_OK '+json.dumps(d['injury_summary'],ensure_ascii=False))
  cache=json.load(open('/opt/football-web/injury-data.json'))
  print('赛程查询状态：'+json.dumps([{'date':v['day'],'state':v['fixture_state'],'fixtures':len(v['fixtures'])} for v in cache['days']],ensure_ascii=False))
  break
 except Exception:
  if attempt==7:raise SystemExit('伤停看板接口检查失败')
  time.sleep(1)
VERIFY_PY
trap - ERR
echo 'INJURY_VIEW_UPDATE_OK：伤停匹配与看板已接入；实际匹配数量见上方。'
echo '刷新看板即可查看。密钥、球员伤停不上传公开仓库；模型概率保持原样。'
echo "备份：$backup"
